// A lap means one clear of every distinct normal room, in any order.
// Replaying a room cannot farm another draw. Total room count is data-driven.
export const DRAW_CONFIG={base:.08,rescueStart:.5,rescueMax:.55};
export function blankProgress(n,reduced=false){return {completed:Array(n).fill(false),gears:Array(n).fill(0),best:Array(n).fill(null),chips:Array(n).fill(0),sound:false,reduced,lap:{number:1,seen:Array(n).fill(false),won:false},pending:null,runLives:3};}
export function readProgress(raw,n,reduced=false){const p=blankProgress(n,reduced);if(!raw||typeof raw!=='object')return p;for(let i=0;i<n;i++){p.completed[i]=raw.completed?.[i]===true;p.gears[i]=Math.min(3,Math.max(0,Number(raw.gears?.[i])||0));p.chips[i]=Math.max(0,Number(raw.chips?.[i])||0);const b=raw.best?.[i];p.best[i]=typeof b==='number'&&Number.isFinite(b)&&b>=0?b:null;}p.runLives=Number.isInteger(raw.runLives)?Math.min(3,Math.max(0,raw.runLives)):3;p.sound=raw.sound===true;p.reduced=typeof raw.reduced==='boolean'?raw.reduced:reduced;if(raw.lap){p.lap.number=Math.max(1,Math.floor(Number(raw.lap.number)||1));p.lap.seen=Array.from({length:n},(_,i)=>raw.lap.seen?.[i]===true);p.lap.won=raw.lap.won===true;}if(raw.pending&&Number.isInteger(raw.pending.index)&&raw.pending.index>=0&&raw.pending.index<n)p.pending=raw.pending;return p;}
export function drawChance(cleared,n,cfg=DRAW_CONFIG){if(cleared>=n)return 1;const fraction=cleared/n;return fraction<=cfg.rescueStart?cfg.base:cfg.base+(cfg.rescueMax-cfg.base)*(fraction-cfg.rescueStart)/(1-cfg.rescueStart);}
export function recordClear(p,index,rng=Math.random){const n=p.completed.length;if(index<0||index>=n)return false;if(p.lap.seen.every(Boolean))p.lap={number:p.lap.number+1,seen:Array(n).fill(false),won:false};if(p.lap.seen[index])return false;p.lap.seen[index]=true;if(p.lap.won||index===n-1)return false;const eligible=n-1,cleared=p.lap.seen.slice(0,-1).filter(Boolean).length;const won=rng()<drawChance(cleared,eligible);if(won)p.lap.won=true;return won;}
